import {
  STREAM_ALL_BNF,
  STREAM_BASE_BNF,
  STREAM_BASE_MAXBLOCK,
  STREAM_BASE_MEL,
  STREAM_BASE_MINBLOCK,
  STREAM_BASE_MINOFF,
  STREAM_BASE_PCM,
  STREAM_BASE_SAMP,
  STREAM_CNT_BNF,
  STREAM_MFCC_FILL,
} from "./constants.js";
import { logMel } from "./mel.js";

function pcmBytesToFloat(bytes, sampleCount) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const out = new Float32Array(sampleCount);
  const n = Math.min(sampleCount, (bytes.byteLength / 2) | 0);
  for (let i = 0; i < n; i++) out[i] = view.getInt16(i * 2, true) / 32768;
  return out;
}

class PcmItem {
  constructor(minoff, blockCount, index) {
    this.minoff = minoff;
    this.blockCount = blockCount;
    this.index = index;
    this.mfcc = null;
  }

  async run(pcmBytes, preBytes, wenet) {
    const allBlocks = this.minoff + this.blockCount + 2 * STREAM_MFCC_FILL;
    const samples = new Float32Array(allBlocks * STREAM_BASE_SAMP);
    const dlen = this.minoff + STREAM_MFCC_FILL;
    const preBlocks = preBytes ? (preBytes.length / STREAM_BASE_PCM) | 0 : 0;
    const blank = dlen - preBlocks;
    if (preBlocks > 0 && preBytes) {
      const pre = pcmBytesToFloat(preBytes, preBlocks * STREAM_BASE_SAMP);
      for (let k = blank; k < dlen; k++) {
        const src = (k - blank) * STREAM_BASE_SAMP;
        const dst = k * STREAM_BASE_SAMP;
        samples.set(pre.subarray(src, src + STREAM_BASE_SAMP), dst);
      }
    }
    const main = pcmBytesToFloat(pcmBytes, this.blockCount * STREAM_BASE_SAMP);
    samples.set(main, (this.minoff + STREAM_MFCC_FILL) * STREAM_BASE_SAMP);

    const mel = logMel(samples);
    const melcnt = (samples.length / 160 + 1) | 0;
    const bnfcnt = (melcnt * 0.25 - 0.75) | 0;
    const bnf = await wenet.run(mel, melcnt, bnfcnt);
    const mfccLen = (this.blockCount + 19) * STREAM_BASE_BNF;
    this.mfcc = new Float32Array(mfccLen);
    const src = this.minoff * STREAM_BASE_BNF;
    const n = Math.min(mfccLen, Math.max(0, bnf.length - src));
    this.mfcc.set(bnf.subarray(src, src + n));
  }

  read(localIndex, dest) {
    const inx = localIndex > 0 ? localIndex - 1 : 0;
    const src = inx * STREAM_BASE_BNF;
    const n = Math.min(STREAM_CNT_BNF * STREAM_BASE_BNF, this.mfcc.length - src);
    dest.fill(0);
    if (n > 0) dest.set(this.mfcc.subarray(src, src + n));
    return n > 0 ? 1 : 0;
  }
}

/**
 * Whole-buffer PCM → BNF windows. Chunking matches PcmFile.prepare (max 50 blocks).
 */
export class FeatureSession {
  constructor(wenet) {
    this.wenet = wenet;
    this.items = [];
    this.ranges = [];
    this.blockCount = 0;
  }

  async ingest(pcm) {
    const buf = Buffer.isBuffer(pcm) ? pcm : Buffer.from(pcm);
    const maxSize = STREAM_BASE_MAXBLOCK * STREAM_BASE_PCM;
    const minSize = STREAM_BASE_MINBLOCK * STREAM_BASE_PCM;
    let pos = 0;
    let lastTail = null;
    const pushChunk = async (chunk) => {
      const blocks = (chunk.length / STREAM_BASE_PCM) | 0;
      const minoff = this.items.length ? STREAM_BASE_MINOFF : 0;
      const item = new PcmItem(minoff, blocks, this.blockCount);
      const pre = lastTail;
      await item.run(chunk, pre, this.wenet);
      this.items.push(item);
      this.ranges.push([this.blockCount, this.blockCount + blocks]);
      this.blockCount += blocks;
      const tailBlocks = Math.min(STREAM_BASE_MINOFF, blocks);
      lastTail = chunk.subarray((blocks - tailBlocks) * STREAM_BASE_PCM);
    };

    while (buf.length - pos >= maxSize) {
      await pushChunk(buf.subarray(pos, pos + maxSize));
      pos += maxSize;
    }
    if (buf.length - pos > 0) {
      let blocks = ((buf.length - pos) / STREAM_BASE_PCM) | 0;
      if (blocks < STREAM_BASE_MINBLOCK) blocks = STREAM_BASE_MINBLOCK;
      const chunk = Buffer.alloc(blocks * STREAM_BASE_PCM);
      buf.copy(chunk, 0, pos, pos + Math.min(buf.length - pos, chunk.length));
      if (chunk.length < minSize && blocks < STREAM_BASE_MINBLOCK) {
        /* padded above */
      }
      await pushChunk(chunk);
    }
    return this.blockCount;
  }

  /** 20×256 window for render index. Returns null when index is past the audio. */
  readWindow(index) {
    if (index < 0 || index >= this.blockCount) return null;
    for (let i = 0; i < this.items.length; i++) {
      const [a, b] = this.ranges[i];
      if (index >= a && index < b) {
        const feat = new Float32Array(STREAM_ALL_BNF / 4);
        this.items[i].read(index - a, feat);
        return feat;
      }
    }
    return null;
  }
}
